481	    /// Add a set of default file type definitions.
482	    pub fn add_defaults(&mut self) -> &mut TypesBuilder {
483	        static MSG: &'static str = "adding a default type should never fail";
484	        for &(names, exts) in DEFAULT_TYPES {
